import CryptoKit
import XCTest
@testable import QAudionEngine

// The Decodable structs mirror the keys of the shared KAT file verbatim (snake_case, no CodingKeys).
// swiftlint:disable identifier_name

/// The six words and the fingerprint a person compares between two phones before PAIR_FIN (CL-2.2):
/// `EarbudPairTranscript.sasWords` / `sasFingerprint`, pinned against `earbud-pair-sas-v1-kat.json`.
///
/// The file is generated by scripts/kat/gen_earbud_pair_sas_kat.py (hashlib only, the word list parsed out
/// of PgpSasWordList.swift) and is shared byte for byte with the Android app, whose
/// `EarbudPairTranscript.sasWords` must give the same words for the same pair_id. The first vector is
/// the one the Android unit test pinned first (pair_id 00..1f -> accrue adult aimless alone apple Athens).
final class EarbudPairSasWordsTests: XCTestCase {

    /// SHA-256 of earbud-pair-sas-v1-kat.json, as pinned by the Android tests too. The file is re-copied, never edited.
    private static let katSha256 = "09f753b1e744e8e241f53ca209a8095e3a568d5e37bd6d5099b6c5a56650657f"

    private struct Vector: Decodable {
        let name: String
        let eid_a_hex: String?
        let eid_b_hex: String?
        let pair_id_hex: String
        let words: [String]
        let fingerprint_hex16: String
        let fingerprint_display: String
    }

    private struct Kat: Decodable {
        let schema: String
        let word_count: Int
        let word_list_sha256: String
        let pair_id_label: String
        let vectors: [Vector]
    }

    private func loadBytes() throws -> Data {
        guard let url = Bundle.module.url(forResource: "earbud-pair-sas-v1-kat", withExtension: "json") else {
            throw XCTestError(.timeoutWhileWaiting, userInfo: [
                NSLocalizedDescriptionKey: "earbud-pair-sas-v1-kat.json not found in Bundle.module"])
        }
        return try Data(contentsOf: url)
    }

    private func load() throws -> Kat {
        try JSONDecoder().decode(Kat.self, from: try loadBytes())
    }

    private func hex(_ s: String) throws -> Data {
        var out = Data()
        var idx = s.startIndex
        while idx < s.endIndex {
            let next = s.index(idx, offsetBy: 2)
            let byte = try XCTUnwrap(UInt8(s[idx..<next], radix: 16))
            out.append(byte)
            idx = next
        }
        return out
    }

    // MARK: - The shared file

    func testTheFileIsTheOneBothAppsPin() throws {
        let digest = SHA256.hash(data: try loadBytes()).map { String(format: "%02x", $0) }.joined()
        XCTAssertEqual(digest, Self.katSha256)
    }

    func testTheWordListIsTheOneTheVectorsWereMadeWith() throws {
        let kat = try load()
        XCTAssertEqual(kat.schema, "qa-earbud-pair-sas-v1-kat:1")
        XCTAssertEqual(kat.word_count, SasConstants.wordCount)
        XCTAssertEqual(kat.pair_id_label, "qa-earbud-excl-pair-v2")
        let listDigest = SHA256.hash(data: Data(PgpSasWordList.words.joined(separator: "\n").utf8))
            .map { String(format: "%02x", $0) }.joined()
        XCTAssertEqual(listDigest, kat.word_list_sha256, "the 256-word list is the same, in the same order, on both platforms")
    }

    func testEveryVectorGivesTheSameWordsAndFingerprintAsTheReferenceImplementation() throws {
        let kat = try load()
        XCTAssertGreaterThanOrEqual(kat.vectors.count, 6)
        for v in kat.vectors {
            let pairId = try hex(v.pair_id_hex)
            XCTAssertEqual(EarbudPairTranscript.sasWords(pairId: pairId), v.words, v.name)
            XCTAssertEqual(EarbudPairTranscript.sasFingerprint(pairId: pairId), v.fingerprint_hex16, v.name)
            XCTAssertEqual(EarbudPairTranscript.sasFingerprintDisplay(pairId: pairId), v.fingerprint_display, v.name)
        }
    }

    func testThePairIdOfEveryVectorWithEarbudIdsIsTheOneThePhonesDerive() throws {
        let kat = try load()
        var checked = 0
        for v in kat.vectors {
            guard let a = v.eid_a_hex, let b = v.eid_b_hex else { continue }
            let pairId = EarbudPairTranscript.pairId(eidA: try hex(a), eidB: try hex(b))
            XCTAssertEqual(pairId, try hex(v.pair_id_hex), v.name)
            checked += 1
        }
        XCTAssertGreaterThanOrEqual(checked, 4)
    }

    // MARK: - Properties the dialog relies on

    func testTheFirstVectorIsTheOneAndroidPinned() {
        let pairId = Data((0..<32).map { UInt8($0) })
        XCTAssertEqual(EarbudPairTranscript.sasWords(pairId: pairId),
                       ["accrue", "adult", "aimless", "alone", "apple", "Athens"])
        XCTAssertEqual(EarbudPairTranscript.sasFingerprintDisplay(pairId: pairId), "0001 0203 0405 0607")
    }

    func testTheWordsAreTheInCallMappingOfTheFirst18BytesOfThePairId() {
        // The same 3-byte big-endian group % list size the in-call SAS (ComputeSasUseCase) applies.
        let eidA = Data((0..<32).map { UInt8(0x01 + $0) })
        let eidB = Data((0..<32).map { UInt8(0x80 + $0) })
        let pairId = EarbudPairTranscript.pairId(eidA: eidA, eidB: eidB)
        var expected: [String] = []
        for i in 0..<SasConstants.wordCount {
            let a = Int(pairId[3 * i])
            let b = Int(pairId[3 * i + 1])
            let c = Int(pairId[3 * i + 2])
            expected.append(PgpSasWordList.words[((a << 16) | (b << 8) | c) % PgpSasWordList.words.count])
        }
        XCTAssertEqual(EarbudPairTranscript.sasWords(pairId: pairId), expected)
        XCTAssertEqual(EarbudPairTranscript.sasWords(pairId: pairId)?.count, 6)
        XCTAssertEqual(EarbudPairTranscript.sasEntropyBytes, 18)
    }

    func testBothPhonesDeriveTheSameWordsWhateverTheOrderOfTheTwoEarbudIds() {
        let eidA = Data((0..<32).map { UInt8(0x01 + $0) })
        let eidB = Data((0..<32).map { UInt8(0x80 + $0) })
        XCTAssertEqual(
            EarbudPairTranscript.sasWords(pairId: EarbudPairTranscript.pairId(eidA: eidA, eidB: eidB)),
            EarbudPairTranscript.sasWords(pairId: EarbudPairTranscript.pairId(eidA: eidB, eidB: eidA)))
    }

    func testASubstitutedEarbudIdentityChangesTheWords() {
        let eidA = Data((0..<32).map { UInt8(0x01 + $0) })
        let eidB = Data((0..<32).map { UInt8(0x80 + $0) })
        let eidMitm = Data((0..<32).map { UInt8(0x55 + $0) })
        let honest = EarbudPairTranscript.sasWords(pairId: EarbudPairTranscript.pairId(eidA: eidA, eidB: eidB))
        let tampered = EarbudPairTranscript.sasWords(pairId: EarbudPairTranscript.pairId(eidA: eidA, eidB: eidMitm))
        XCTAssertNotNil(honest)
        XCTAssertNotEqual(honest, tampered)
    }

    func testAPairIdThatIsNot32BytesGivesNothing() {
        for size in [0, 16, 31, 33, 64] {
            let pairId = Data(count: size)
            XCTAssertNil(EarbudPairTranscript.sasWords(pairId: pairId), "size \(size)")
            XCTAssertNil(EarbudPairTranscript.sasFingerprint(pairId: pairId), "size \(size)")
            XCTAssertNil(EarbudPairTranscript.sasFingerprintDisplay(pairId: pairId), "size \(size)")
        }
    }
}
